import Component from 'flarum/common/Component';
import Link from 'flarum/common/components/Link';
import { seriesUrl } from '../../common/urls';
import Cover from './Cover';
import { t } from '../util';

/** A series in a grid: the cover, title, author, status and chapter count. */
export default class SeriesCard extends Component {
  view() {
    const series = this.attrs.series;
    return m(Link, {
      className: "AnthologyCard",
      href: seriesUrl(series)
    }, m("span", {
      className: "AnthologyCard-cover"
    }, m(Cover, {
      url: series.coverUrl,
      title: series.title
    }), m("span", {
      className: 'AnthologyStatus AnthologyStatus--' + series.status
    }, t('status.' + series.status))), m("span", {
      className: "AnthologyCard-body"
    }, m("span", {
      className: "AnthologyCard-title"
    }, series.title), series.author ? m("span", {
      className: "AnthologyCard-author"
    }, t('card.by', {
      author: series.author.displayName
    })) : null, m("span", {
      className: "AnthologyCard-meta"
    }, t('card.chapters', {
      count: series.chapterCount
    }), series.followerCount ? m('[', null, " \xB7 ", t('card.followers', {
      count: series.followerCount
    })) : null)));
  }
}
flarum.reg.add('ernestdefoe-anthology', 'forum/components/SeriesCard', SeriesCard);